@@preprocessing
<%_ {
const rawData=getMessageVar('stat_data',{defaults:{}});
const data=(rawData&&typeof rawData==='object')?rawData:{};
const safeGet=(source,path,fallback)=>{
  const keys=Array.isArray(path)?path:String(path||'').split('.').filter(Boolean);
  let value=source;
  for(const key of keys){
    if(value===null||value===undefined||typeof value!=='object'||!(key in value))return fallback;
    value=value[key];
  }
  return value===undefined?fallback:value;
};
const asObject=value=>(value&&typeof value==='object'&&!Array.isArray(value))?value:{};
const asArray=value=>Array.isArray(value)?value:[];
const world=asObject(safeGet(data,['世界'],{}));
const player=asObject(safeGet(data,['玩家'],{}));
const characters=asObject(safeGet(data,['角色'],{}));
const tasks=asObject(safeGet(data,['任務'],{}));
const system=asObject(safeGet(data,['系統'],{}));
const sceneIds=new Set(asArray(safeGet(world,['當前場景角色ID'],[])).map(String));
const partyMembers=asObject(safeGet(player,['隊伍','成員'],{}));
const partyIds=new Set(Object.keys(partyMembers));
const activeTasks=Object.fromEntries(Object.entries(tasks).filter(([,task])=>{
  const state=safeGet(asObject(task),['狀態'],'');
  return ['候選','可接取','進行中'].includes(String(state));
}));
for(const taskValue of Object.values(activeTasks)){
  const task=asObject(taskValue);
  for(const id of asArray(safeGet(task,['參與者ID'],[])))sceneIds.add(String(id));
  const issuer=safeGet(task,['發起者ID'],'');
  if(issuer)sceneIds.add(String(issuer));
}
for(const id of partyIds)sceneIds.add(id);
const relevantCharacters=Object.fromEntries([...sceneIds].filter(id=>id&&characters[id]).map(id=>[id,characters[id]]));
const bag=asObject(safeGet(player,['背包'],{}));
const bagSummary=Object.fromEntries(Object.entries(bag).map(([id,itemValue])=>{
  const item=asObject(itemValue);
  return [id,{
    模板ID:safeGet(item,['模板ID'],''),顯示名稱:safeGet(item,['顯示名稱'],''),類別:safeGet(item,['類別'],''),
    子類:safeGet(item,['子類'],''),品質:safeGet(item,['品質'],''),數量:safeGet(item,['數量'],0),
    耐久:safeGet(item,['耐久'],null),可交易:safeGet(item,['可交易'],false),鑑定狀態:safeGet(item,['鑑定狀態'],'')
  }];
}));
const equipment=asObject(safeGet(player,['裝備'],{}));
let derived={};
try{
  const api=(typeof globalThis!=='undefined')?globalThis.SAOP_V5_API:null;
  if(api&&typeof api.derivedStats==='function')derived=api.derivedStats(data,'player')||{};
}catch(_){derived={};}
const pending=asObject(safeGet(system,['待確認行動'],{}));
const recentLogs=asArray(safeGet(system,['行動日誌'],[])).slice(-8);
_%>
<SAO_RUNTIME_CONTEXT version="5.1.1">
時間地點：<%- safeGet(world,['日期'],'2022-11-06') %> <%- safeGet(world,['時間'],'13:25') %>｜第<%- safeGet(world,['當前樓層'],1) %>層｜<%- safeGet(world,['當前區域'],'起始之鎮') %>｜<%- safeGet(world,['詳細地點'],'中央廣場') %>｜<%- safeGet(world,['區域狀態'],'圈內') %>
場景：<%- safeGet(world,['場景狀態'],'日常') %>｜天氣：<%- safeGet(world,['天氣'],'晴') %>
玩家：<%- safeGet(player,['名稱'],'{{user}}') %>｜LV.<%- safeGet(player,['等級'],1) %>｜EXP <%- safeGet(player,['經驗','當前'],0) %>/<%- safeGet(player,['經驗','下一級'],100) %>｜HP <%- safeGet(player,['HP','當前'],250) %>/<%- safeGet(player,['HP','最大'],250) %>｜STR <%- safeGet(player,['屬性','STR'],5) %>｜AGI <%- safeGet(player,['屬性','AGI'],5) %>｜可分配 <%- safeGet(player,['屬性','可分配點數'],0) %>｜<%- safeGet(player,['Col'],500) %> Col
衍生顯示值（只讀、由腳本即時計算）：<%- JSON.stringify(derived) %>
裝備：<%- JSON.stringify(equipment) %>
背包摘要：<%- JSON.stringify(bagSummary) %>
技能：<%- JSON.stringify(asObject(safeGet(player,['技能'],{}))) %>
隊伍：<%- JSON.stringify(asObject(safeGet(player,['隊伍'],{}))) %>
當前遭遇：<%- JSON.stringify(safeGet(world,['當前遭遇'],null)) %>
當前樓層檔案：<%- JSON.stringify(asObject(safeGet(world,['當前樓層檔案'],{}))) %>
當前相關角色：<%- JSON.stringify(relevantCharacters) %>
活動任務：<%- JSON.stringify(activeTasks) %>
當前事件：<%- JSON.stringify(asObject(safeGet(world,['事件'],{}))) %>
當前組織：<%- JSON.stringify(asObject(safeGet(world,['組織'],{}))) %>
待確認行動：<%- JSON.stringify(pending) %>
最近確定性日誌：<%- JSON.stringify(recentLogs) %>

<AUTHORITY>
1. 正文只敘事，不輸出變量標籤；額外變量模型負責直接變量更新或建立UnifiedAction。
2. Col、HP、經驗、屬性、背包、裝備、技能、隊伍、好感數值、耐久、狀態、時間、跨樓層移動與所有結算結果，只能由v5唯一調度器更新。
3. 釣魚與採集可由文字行動建立「生活技能」行動。玩家自己的鍛造、裁縫、料理、鑑定可由面板建立行動。
4. NPC可提供固定價格、固定材料、固定產出的簡化服務，包括修理、鑑定、旅店、固定料理、交通、鍛造委託、裁縫委託、料理委託與鑑定委託；不模擬NPC熟練度、成功率、工作台或代工隊列。
5. 確定性結果只採用MVU最終值與「系統.行動日誌」。沒有完成日誌前，只能描寫提案、嘗試、等待確認或服務受理。
6. 未列入當前相關角色的離場人物不得逐回合更新。再次接觸時再依時間與已發生事件一次補算。
</AUTHORITY>
</SAO_RUNTIME_CONTEXT>
<%_ } _%>

